,('ec000036-0000-0000-0000-000000000036', NULL, 'Salad trứng bơ', 'Salad trứng và bơ đủ chất cho bữa tối nhanh.', 10, 10, 20, 1, 'Easy', 'Dinner', 32000, '[]', NULL, NULL, true, now()),
