,('ec000101-0000-0000-0000-000000000101', 'fd000011-0000-0000-0000-000000000011', 'Phở bò Hà Nội chuẩn vị', 'Phở bò nước dùng thanh ngọt từ xương bò và gừng nướng', 30, 180, 210, 4, 'Hard', 'Lunch', 80000, '["Bước 1: Rửa sạch xương bò, chần qua nước sôi để loại bỏ tạp chất.", "Bước 2: Nướng gừng và hành tím trên lửa than cho thơm, cho vào nồi nước dùng cùng xương bò, gia vị (muối, đường phèn, hoa hồi, quế).", "Bước 3: Hầm nhỏ lửa ít nhất 4 tiếng cho nước dùng ngọt và trong.", "Bước 4: Trụng bánh phở qua nước sôi, xếp ra tô cùng thịt bò thái mỏng, chan nước dùng nóng, rắc hành lá và rau thơm."]', 'https://images.unsplash.com/photo-1583085314093-10c834952627?w=400', NULL, true, now())
,('ec000102-0000-0000-0000-000000000102', 'fd000012-0000-0000-0000-000000000012', 'Bún chả Hà Nội', 'Bún chả thịt nướng than hoa ăn kèm nước mắm chua ngọt', 25, 30, 55, 2, 'Medium', 'Lunch', 70000, '["Bước 1: Trộn thịt heo xay với hành tím băm, tỏi, nước mắm, đường, tiêu và chút dầu ăn.", "Bước 2: Vo viên và dàn mỏng thành miếng chả, nướng trên than hoa.", "Bước 3: Pha nước mắm chua ngọt với tỷ lệ 1:1:1 (mắm-đường-nước) thêm tỏi ớt băm.", "Bước 4: Trụng bún tươi, xếp rau sống, chả nướng, chan nước mắm và thưởng thức."]', 'https://images.unsplash.com/photo-1596797038530-2c107229654b?w=400', NULL, true, now())
,('ec000103-0000-0000-0000-000000000103', 'fd000013-0000-0000-0000-000000000013', 'Bún bò Huế cay nồng', 'Bún bò Huế đậm đà với sả, mắm ruốc và chân giò', 40, 90, 130, 4, 'Hard', 'Lunch', 120000, '["Bước 1: Nấu nước dùng từ xương bò và chân giò với sả đập dập, hành tím nướng, gừng.", "Bước 2: Cho mắm ruốc Huế vào nước dùng đã lọc, nêm nếm vừa ăn.", "Bước 3: Thái mỏng thịt bò, huyết (nếu có), cho vào nồi nước dùng.", "Bước 4: Trụng bún, chan nước dùng, thêm hành lá, rau muống chẻ, chanh, ớt."]', 'https://images.unsplash.com/photo-1625220194771-7ebedd0b40b8?w=400', NULL, true, now())
,('ec000104-0000-0000-0000-000000000104', 'fd000014-0000-0000-0000-000000000014', 'Mì quảng gà miền Trung', 'Mì quảng sợi vàng dai với nước dùng sánh đậm đà từ nghệ và gà ta', 25, 40, 65, 2, 'Medium', 'Lunch', 90000, '["Bước 1: Phi thơm tỏi, hành tím với dầu điều và bột nghệ cho ra màu vàng đặc trưng.", "Bước 2: Xào gà ta xé sợi với gia vị, nước dùng xương gà.", "Bước 3: Trụng mì quảng qua nước sôi, xếp ra tô cùng gà, đậu phộng rang, bánh tráng nướng.", "Bước 4: Chan nước dùng vừa đủ (ít nước), rắc hành lá, rau thơm, ớt tươi."]', 'https://images.unsplash.com/photo-1596797038530-2c107229654b?w=400', NULL, true, now())
,('ec000105-0000-0000-0000-000000000105', 'fd000015-0000-0000-0000-000000000015', 'Cơm tấm sườn bì chả', 'Cơm tấm Sài Gòn với sườn nướng, bì, chả trứng và nước mắm', 30, 45, 75, 2, 'Medium', 'Lunch', 80000, '["Bước 1: Ướp sườn heo với nước mắm, tỏi, đường, tiêu, sả trong 2 tiếng.", "Bước 2: Nấu cơm tấm với nước vừa đủ cho hạt tơi mềm.", "Bước 3: Nướng sườn trên than hoa, trứng ốp la riêng, bì heo trộn thính.", "Bước 4: Xếp cơm ra đĩa, bày sườn, bì, chả, trứng, dưa leo, cà chua, chan nước mắm pha."]', 'https://images.unsplash.com/photo-1625372227556-2fd8c2bd3642?w=400', NULL, true, now())
,('ec000106-0000-0000-0000-000000000106', 'fd000016-0000-0000-0000-000000000016', 'Hủ tiếu Nam Vang', 'Hủ tiếu nước dùng ngọt thanh với tôm, thịt, gan và trứng', 25, 60, 85, 2, 'Medium', 'Lunch', 80000, '["Bước 1: Nấu nước dùng từ xương heo và tôm khô cho ngọt.", "Bước 2: Luộc tôm, trụng thịt heo, gan heo, trứng cút.", "Bước 3: Trụng sợi hủ tiếu, xếp ra tô cùng các loại nhân.", "Bước 4: Chan nước dùng nóng, rắc hành lá, giá đỗ, rau thơm."]', 'https://images.unsplash.com/photo-1569562211093-4ed0d0758f12?w=400', NULL, true, now())
,('ec000107-0000-0000-0000-000000000107', 'fd000023-0000-0000-0000-000000000023', 'Bánh cuốn Hà Nội', 'Bánh cuốn mỏng nhân thịt bằm và nấm hương ăn với chả lụa', 30, 25, 55, 2, 'Medium', 'Breakfast', 50000, '["Bước 1: Pha bột gạo với nước theo tỷ lệ, khuấy đều cho mịn.", "Bước 2: Xào nhân thịt heo bằm với nấm hương, hành tím, gia vị.", "Bước 3: Tráng bột mỏng lên khuôn hấp cho chín, cuộn nhân bên trong.", "Bước 4: Xếp bánh cuốn ra đĩa, ăn kèm chả lụa, hành phi, nước mắm chua ngọt."]', 'https://images.unsplash.com/photo-1559314809-0d155014e29e?w=400', NULL, true, now())
,('ec000108-0000-0000-0000-000000000108', 'fd000024-0000-0000-0000-000000000024', 'Bánh gối giòn tan', 'Bánh gối nhân thịt và rau củ chiên giòn', 25, 30, 55, 1, 'Medium', 'Snack', 35000, '["Bước 1: Trộn bột mì với nước và chút muối, nhào mịn, để bột nghỉ 20 phút.", "Bước 2: Xào nhân thịt heo bằm với miến, nấm hương, cà rốt, hành tây.", "Bước 3: Cán bột mỏng, gói nhân thành hình bánh gối, gấp mép tạo hình.", "Bước 4: Chiên ngập dầu đến khi vỏ vàng giòn, vớt ra để ráo, ăn kèm nước chấm chua ngọt."]', 'https://images.unsplash.com/photo-1567620905732-2d1ec7ab7445?w=400', NULL, true, now())
,('ec000109-0000-0000-0000-000000000109', 'fd000043-0000-0000-0000-000000000043', 'Bún mắm miền Tây', 'Bún mắm đậm đà mùi mắm cá linh đặc sản miền Tây', 30, 60, 90, 2, 'Hard', 'Lunch', 90000, '["Bước 1: Pha mắm cá linh với nước theo tỷ lệ 1:4, lọc qua ray cho sạch xương cá.", "Bước 2: Nấu nước dùng mắm với sả, tỏi, ớt, đường thốt nốt cho cân vị.", "Bước 3: Xào thịt heo quay và tôm với hành tím.", "Bước 4: Trụng bún, xếp nhân, rau sống, chan nước mắm nóng, thêm chanh ớt."]', 'https://images.unsplash.com/photo-1596797038530-2c107229654b?w=400', NULL, true, now())
,('ec000110-0000-0000-0000-000000000110', 'fd000045-0000-0000-0000-000000000045', 'Bánh canh cua đồng', 'Bánh canh nước dùng ngọt từ cua đồng xay nhuyễn', 30, 60, 90, 2, 'Medium', 'Lunch', 100000, '["Bước 1: Xay cua đồng với nước, lọc lấy nước cốt, đun sôi cho gạch cua nổi lên.", "Bước 2: Phi thơm hành tím, tỏi với dầu, cho nước cua vào nấu cùng xương heo.", "Bước 3: Trụng sợi bánh canh, xếp ra tô cùng tôm, thịt heo.", "Bước 4: Chan nước dùng cua nóng, rắc hành lá, tiêu, ớt, ăn kèm rau muống."]', 'https://images.unsplash.com/photo-1625220194771-7ebedd0b40b8?w=400', NULL, true, now()),
('ec000201-0000-0000-0000-000000000201', 'fd000019-0000-0000-0000-000000000019', 'Nem nướng Nha Trang', 'Nem nướng dai ngon cuốn bánh tráng với rau sống', 15, 25, 40, 1, 'Easy', 'Món mặn', 40000, '["Bước 1: Sơ chế nguyên liệu cho Nem nướng Nha Trang.", "Bước 2: Ướp gia vị và để ngấm 10-15 phút.", "Bước 3: Xào/nướng/chiên đến khi chín tới.", "Bước 4: Trang trí và thưởng thức nóng."]', 'https://images.unsplash.com/photo-1604503468506-a8da13d82791?w=400', NULL, true, now())
